from collections import deque

def count_connected_components(grid, color):
    rows = len(grid)
    cols = len(grid[0])

    visited = set()
    count = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == color and (i, j) not in visited:
                # BFS to find connected component
                queue = deque([(i, j)])
                visited.add((i, j))
                count += 1
                while queue:
                    r, c = queue.popleft()
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
    return count

