from collections import deque

def count_components(grid, target):
    n, m = len(grid), len(grid[0])
    visited = set()
    for i in range(n):
        for j in range(m):
            if grid[i][j] == target and (i,j) not in visited:
                # BFS
                q = deque([(i,j)])
                visited.add((i,j))
                while q:
                    r, c = q.popleft()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == target and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
    return len(visited), visited

